import {MODEL_VERSION} from './vehicle-models.js';
import {MODEL_BUILD_ID} from './model-build.js';

let deployment=null,pending=null;
// The deployment file is generated by Pages from the committed tree. A stale
// cache or a local preview must never borrow a different build's commit ID.
export function getRuntimeIdentity(){
  const matches=deployment?.modelVersion===MODEL_VERSION&&deployment?.modelBuildId===MODEL_BUILD_ID;
  return{modelVersion:MODEL_VERSION,modelBuildId:MODEL_BUILD_ID,
    sourceCommit:matches?deployment.sourceCommit:null,sourceTree:matches?deployment.sourceTree:null,
    sourceIdentityStatus:matches?'matched-current-build':deployment?'deployment-build-mismatch':'not-available'};
}
export function loadRuntimeIdentity(){
  if(!pending)pending=typeof window==='object'&&typeof fetch==='function'
    ?fetch(new URL('./deployment.json',import.meta.url),{cache:'no-store'}).then(r=>r.ok?r.json():null).then(value=>{deployment=value;return getRuntimeIdentity();}).catch(()=>getRuntimeIdentity())
    :Promise.resolve(getRuntimeIdentity());
  return pending;
}
